 class Program {
  [STAThread] static int Main(string[] args) {
   if(args.Contains("--verify-ui"))return Tests.UiRun();
   if(args.Contains("--self-test"))return Tests.Run();
   bool test=args.Contains("--ui-test");string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),test?"DeskFlow-UITest":"DeskFlow");
   bool first;using(var mutex=new Mutex(true,test?"Local\\DeskFlow-UITest":"Local\\DeskFlow-Widget",out first)){
    if(!first){Forms.MessageBox.Show("나날이 이미 실행 중입니다. 알림 영역의 캘린더 아이콘을 두 번 클릭해 주세요.");return 0;}
    try{var app=new Application();app.DispatcherUnhandledException+=(s,e)=>{Forms.MessageBox.Show("작업을 완료하지 못했습니다.\n"+e.Exception.Message,"나날");e.Handled=true;};var widget=new Widget(new Store(dir));widget.Window.Loaded+=(s,e)=>{Widget.MarkUpdateHealthy(args,dir);if(args.Contains("--start-hidden"))widget.Window.Hide();if(args.Contains("--update-verify-exit"))widget.Window.Close();};app.Run(widget.Window);return 0;}
    catch(Exception e){Forms.MessageBox.Show(e.Message,"나날 시작 오류");return 1;}
   }
  }
 }
